                seen[v] = True
                depth[v] = depth[u] + 1
                up[0][v] = u
                mx[0][v] = w
                queue.append(v)
    for j in range(1, LOG):
        for v in range(1, n + 1):
            mid = up[j - 1][v]
            up[j][v] = up[j - 1][mid]
            mx[j][v] = max(mx[j - 1][v], mx[j - 1][mid])

    def path_max(u, v):
        best = 0
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if diff >> j & 1:
                best = max(best, mx[j][u])
                u = up[j][u]
