#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    vector<int> order(m);
    for (int i = 0; i < m; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return edges[x][2] < edges[y][2]; });
    vector<char> inTree(m, 0);
    long long total = 0;
    vector<vector<pair<int, long long>>> tree(n + 1);
    for (int i : order) {
        if (unite((int)edges[i][0], (int)edges[i][1])) {
            inTree[i] = 1;
            total += edges[i][2];
            tree[edges[i][0]].push_back({(int)edges[i][1], edges[i][2]});
            tree[edges[i][1]].push_back({(int)edges[i][0], edges[i][2]});
        }
    }
    if (m == n - 1) {
        cout << -1 << "\n";
    } else {
        const int LOG = 13;
        vector<int> depth(n + 1, 0);
        vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
        vector<vector<long long>> mx(LOG, vector<long long>(n + 1, 0));
        vector<char> seen(n + 1, 0);
        seen[1] = 1;
        vector<int> queue = {1};
        for (size_t i = 0; i < queue.size(); i++) {
            int u = queue[i];
            for (const auto& edge : tree[u]) {
                int v = edge.first;
                if (!seen[v]) {
                    seen[v] = 1;
                    depth[v] = depth[u] + 1;
                    up[0][v] = u;
                    mx[0][v] = edge.second;
                    queue.push_back(v);
                }
            }
        }
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= n; v++) {
                int mid = up[j - 1][v];
                up[j][v] = up[j - 1][mid];
                mx[j][v] = max(mx[j - 1][v], mx[j - 1][mid]);
            }
        }
        auto pathMax = [&](int u, int v) {
            long long best = 0;
            if (depth[u] < depth[v]) swap(u, v);
            int diff = depth[u] - depth[v];
            for (int j = 0; j < LOG; j++) {
                if ((diff >> j) & 1) {
                    best = max(best, mx[j][u]);
                    u = up[j][u];
                }
            }
            if (u == v) return best;
            for (int j = LOG - 1; j >= 0; j--) {
                if (up[j][u] != up[j][v]) {
                    best = max(best, max(mx[j][u], mx[j][v]));
                    u = up[j][u];
                    v = up[j][v];
                }
            }
            return max(best, max(mx[0][u], mx[0][v]));
        };
        long long extra = 1000000000000000000LL;
        for (int i = 0; i < m; i++) {
            if (!inTree[i]) extra = min(extra, edges[i][2] - pathMax((int)edges[i][0], (int)edges[i][1]));
        }
        cout << total + extra << "\n";
    }

    return 0;
}

