import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][3];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n, count = (int) m;
        parent = new int[nodes + 1];
        sizes = new int[nodes + 1];
        for (int v = 0; v <= nodes; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        Integer[] order = new Integer[count];
        for (int i = 0; i < count; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> Long.compare(edges[x][2], edges[y][2]));
        boolean[] inTree = new boolean[count];
        long total = 0;
        List<List<long[]>> tree = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) tree.add(new ArrayList<>());
        for (int i : order) {
            if (unite((int) edges[i][0], (int) edges[i][1])) {
                inTree[i] = true;
                total += edges[i][2];
                tree.get((int) edges[i][0]).add(new long[] {edges[i][1], edges[i][2]});
                tree.get((int) edges[i][1]).add(new long[] {edges[i][0], edges[i][2]});
            }
        }
        if (count == nodes - 1) {
            System.out.println(-1);
        } else {
            int LOG = 13;
            int[] depth = new int[nodes + 1];
            int[][] up = new int[LOG][nodes + 1];
            long[][] mx = new long[LOG][nodes + 1];
            boolean[] seen = new boolean[nodes + 1];
            seen[1] = true;
            List<Integer> queue = new ArrayList<>();
            queue.add(1);
            for (int i = 0; i < queue.size(); i++) {
                int u = queue.get(i);
                for (long[] edge : tree.get(u)) {
                    int v = (int) edge[0];
                    if (!seen[v]) {
                        seen[v] = true;
                        depth[v] = depth[u] + 1;
                        up[0][v] = u;
                        mx[0][v] = edge[1];
                        queue.add(v);
                    }
                }
            }
            for (int j = 1; j < LOG; j++) {
                for (int v = 1; v <= nodes; v++) {
                    int mid = up[j - 1][v];
                    up[j][v] = up[j - 1][mid];
                    mx[j][v] = Math.max(mx[j - 1][v], mx[j - 1][mid]);
                }
            }
            long extra = 1000000000000000000L;
            for (int i = 0; i < count; i++) {
                if (inTree[i]) continue;
                int u = (int) edges[i][0], v = (int) edges[i][1];
                long best = 0;
                if (depth[u] < depth[v]) {
                    int t = u;
                    u = v;
                    v = t;
                }
                int diff = depth[u] - depth[v];
                for (int j = 0; j < LOG; j++) {
                    if (((diff >> j) & 1) != 0) {
                        best = Math.max(best, mx[j][u]);
                        u = up[j][u];
                    }
                }
                if (u != v) {
                    for (int j = LOG - 1; j >= 0; j--) {
                        if (up[j][u] != up[j][v]) {
                            best = Math.max(best, Math.max(mx[j][u], mx[j][v]));
                            u = up[j][u];
                            v = up[j][v];
                        }
                    }
                    best = Math.max(best, Math.max(mx[0][u], mx[0][v]));
                }
                extra = Math.min(extra, edges[i][2] - best);
            }
            System.out.println(total + extra);
        }
    }
}
